import{_ as e,c as p,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"小過","description":"高岛易断 - 小過","frontmatter":{"title":"小過","description":"高岛易断 - 小過"},"headers":[],"relativePath":"zh/classics/takashima/062.md","filePath":"zh/classics/takashima/062.md"}'),i={name:"zh/classics/takashima/062.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="小過" tabindex="-1">小過 <a class="header-anchor" href="#小過" aria-label="Permalink to “小過”">​</a></h1><h2 id="小過-1" tabindex="-1">小過 <a class="header-anchor" href="#小過-1" aria-label="Permalink to “小過”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>小过：亨利贞，可小事，不可大事。飞鸟遗之音，不宜上，宜下，大吉。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《小过》者，阴过乎阳，即“行过乎恭，丧过乎哀，用过乎俭”之谓也，过在细故，道乃可通，故曰“小过亨”。“利贞”者，矫世励俗，利在归正，故曰“利贞”。四阴擅权在外，二阳逼处于中，柔弱无力，不足以当大任，只可小受而已，故曰“可小事，不可大事”。《震》为鹄，又为音，故曰“飞鸟遗之音”，遗其音者，哀鸣之声也。飞鸟过高，欲下不得，哀鸣求救，上则愈危，下则犹得安，故曰“不宜上，宜下，大吉”，吉在下也。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>山上有雷，小过。君子以行过乎恭，丧过乎哀，用过乎俭。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>《震》雷者，动而不止，《艮》者，止而不动，山上有雷，是雷为山所止，雷必小矣，故为《小过》。君子取其象以制行，而行不嫌其过恭；取其象以居丧，而丧不嫌其过哀；取其象以致用，而用不嫌其过俭。盖曰“行”，曰“丧”，曰“用”，皆动也，象《震》；曰“恭”，曰“哀”，曰“俭”，皆止也，象《艮》；其过恭、过哀、过俭，皆所以矫一时之弊也，以其非中行也，谓之《小过》，然亦足矫世而励俗焉。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：运途清高，有不屑于同污流俗之概。</p><p>○　问营商：因一时价值过高，不合时宜，买卖均难。</p><p>○　问功名：以其不谐时俗，反为人忌。</p><p>○　问战征：屯营山上，地位过高，进退俱难。</p><p>○　问婚姻：想是老夫女妻，年岁相去过远。</p><p>○　问家宅：此宅想在高山。</p><p>○　问疾病：是过寒过热之症，须调剂得中。</p><p>○　问六甲：生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>“以”者，即左右之曰以是也。鸟以翼而飞，初与上，象取两翼，故皆言“飞鸟”。《小过》“不宜上，宜下”，初在下，更不宜上，飞则振冀直上，欲下不能，其凶可知也，故曰“飞鸟以凶”。初居《艮》止之始，本无飞象，初与上相终始，上居《震》动之终，上之鸟，动而思飞。初上分为两翼，一翼飞，一翼不能独止，故飞则俱飞，凶亦俱凶。《象传》释以“不可如何”，谓“上逆而下顺”，初在下，乃不顺下而逆上，是自取其凶也，亦无可如何耳。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问时运：不安本分，妄思风腾上进，凶。</p><p>○　问营商：力小而图大，位卑而谋高，不自量力，必致败也。</p><p>○　问功名：宜卑小自安。</p><p>○　问战征：初在《艮》下，宜按兵不动。</p><p>○　问婚姻：宜门户相当，不宜攀结高亲。</p><p>○　问家宅：屋宇以低小为宜。</p><p>○　问疾病：神魂飞越，凶。</p><p>○　问六甲：生男。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某来，请占谋事成否，筮得《小过》之《丰》。</p><p>断曰：鸟本以栖集为安，以飞翔为劳，飞而不下，是鸟不得其栖息矣，是以凶也，犹如人惶惶道路，有不遑安处之状。今君占谋事，得此爻辞，知君所谋，意欲舍小图大，去低就高，为力谋上进之事。就爻象而论，鸟之飞，愈上愈危，欲下不得，喻言君之谋事，愈大愈难，不特其事不成，即他日欲退而就小，而亦不能也。劝君安心退守，不作妄想，斯可免凶也。</p><p>二十七年冬至，占二十八年我国与俄国交际，筮得《小过》之《丰》。</p><p>断曰：初爻处《艮》之下，《艮》，止也，本不宜动，乃鸟以动而飞，是失《艮》之止，以从《震》之动，舍顺就逆，是以凶也。《彖》辞曰，“不宜上，宜下”，鸟能安其在下，则凶可免矣。今占我国与俄国交际，得此爻象，是当以内卦《艮》属我，外卦《震》属俄。在俄，虎视耽耽，只知动兵争强；我与清交战，乃俄若忌我之胜，有跃跃欲动之意。彼动而我亦不能不动，故初与上，皆言“飞鸟”，是象之发现在此。果若两动，则必两凶，当谨守宜下之戒，则可以免凶。后我与清国媾和，法顺下之旨，乃得平和结局。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>《易》例，阴阳相应，为君臣，为夫妇，取其配偶；无应者，或为父子，或为等夷，或为嫡媵，或为妣妇，取其同类。五为父母之位，亦为祖妣之位，阳爻为父为祖，阴爻为母为祖妣。五为父母，则必以二为子；五为祖妣，则必以二为孙。今二五皆阴，而不相应，有妣妇之配，故曰“过其祖，遇其妣”。常例五为君，此卦君当谓上，五则臣也，故臣谓二五。过四而与五遇，则止于五而不上，故曰“不及其君，遇其臣”。可过而过，不及而不过，为能得经权之中，无过不及之偏，故“无咎”。且二五以柔相亲，五尊二卑，卑之于尊，弗过则可承其礼遇，过则有逾越之嫌，故五视上虽为臣，而二不可遇也，不可遇，则二于上，但觉庙高堂远，瞻仰弗及矣。不可过而不过，安于“宜下”，夫复何咎？此《小过》之最善者也。《象传》之所释者以此。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：运途平顺，不得其全，犹得其半，亦可无咎矣。</p><p>○　问营商：贸资以往，虽未得满载而归，亦足称十得其五矣。</p><p>○　问功名：不得其上，已获其中。</p><p>○　问战征：已得斩其将，拔其旗，夫复何咎？</p><p>○　问疾病：药力未到。</p><p>○　问婚姻：恐非正配。</p><p>○　问家宅：宅神不安。</p><p>○　问六甲：生男。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治十八年七月，余避暑游伊香保，有号其角堂主人者，工俳谐，访余旅寓，自云：近来俳谐道衰，是愚所叹息也。每年朝廷有和歌御制，许民间咸相赓和，独俳谐无闻，愚窃欲上俳谐天览之议，闻先生通晓神《易》，请占成否。筮得《小过》之《恒》。</p><p>断曰：此爻六二重阴，柔弱无力，爻曰遇妣遇臣，所遇皆阴象，又曰“不及其君”，是明言不能上达君听也。足下占俳谐上呈，得此爻辞，在俳谐为和歌变体，主文谲谏，片字只句，颇得温和厚平之旨，固非徒玩弄风月已也。爻辞曰“过其祖，遇其妣，不及其君，遇其臣，即此论之，虽不及上献之于宫闱，或陈之于贵显，当必有风雅相尚者矣，故曰“无咎”。其角堂主人得此占，大为心喜。</p><p>二十九年六月，朝鲜人朴泳孝，归自美国，访我山庄，曰：朝鲜政府，同志者以王内命，促余归国，余犹疑未决，请为一占，以定行止。筮得《小过》之《恒》。</p><p>断曰：爻辞曰“不及其君，已可见促足下归国者，不出于君命，或出自臣下之意也。爻象六二重阴，阳多吉，阴多凶，去恐有祸。且卦体上动下止，贵国政府来召，应外卦之动，内卦《艮》止，已示足下不归之兆。爻象如此，在足下虽故国殷情，还宜自爱，切勿匆匆归去。朴泳孝闻此占，遂绝归计。后闻朝鲜政府，党类倾轧，廷臣多有以冤罪就刑者。</p><p>三十年，占我国与英国交际，筮得《小过》之《恒》。</p><p>断曰：我国与英国，地隔重洋，相距数万里，两国所以联盟者，全藉使臣之通其好耳，即爻辞所云“不及其君，遇其臣”之谓也。就卦位言，内卦属我，外卦属英，二五各居卦中；就卦象言，全卦象取飞鸟，二五为鸟两翼，飞则两翼俱动，足见我两国联合之象，相挟相助，俨同一体，故“无咎”也。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>三处下卦之上，重刚不中，《彖》所谓“不可大事”者，三四当之。且三为多凶之地，过将焉往？故爻曰“弗过”。卦体刚阳，一画横亘其中，有防之象，《艮》，止也，有防之义。防者，止其过也，止其过，即当“弗过”。上互《兑》，《兑》为金刀，有戕之象，三窬防而过，或有从而戕之者矣。“或”虽为未然之事，而其势已岌岌可危，故“凶”。《象传》曰“凶如何也”；谓纯刚既足召祸，强进更必致灾，凶由自取，无如何也。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问时运：运途不正，谨慎自防，尚可免祸。</p><p>○　问营商：贩运出外，防遇盗劫之凶，宜勿前进。</p><p>○　问功名：切弗往求，求则有祸。</p><p>○　问婚姻：非婚媾，则寇雠也，宜防。</p><p>○　问家宅：有凶祸临门，宜谨防之。</p><p>○　问疾病：防是刀伤，凶。</p><p>○　问失物：不必追寻，方可免灾。</p><p>○　问讼事：防干大辟。</p><p>○　问六甲：生男，难育。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>横滨商人，桔屋矶兵卫氏来，曰：友人左右田金作，今朝遣店童，送纸币三千元于三井银行，至午后未还，往问三井银行，云并未送来，于是驰人遍索，不得踪迹。请为一占，明示方向。筮得《小过》之《豫》。</p><p>断曰：卦体《震》上《艮》下，《艮》为少男，《震》为长男，三爻重刚不中，正当二男之象。辞曰“弗过，防之，从或戕之，凶”，三在内，四在外，言三须谨防，弗过四处，若窬防而过，恐遭戕贼之祸。据此爻象，此人必已遭害，在谋害者，必是相熟之人，非外来之盗贼也。爻在第三，三为鸟身，一时不能飞逸，五爻曰“公弋取彼在穴”，自三至五，为三日，不出三日，凶手必可捕获也。后三日，果得此死尸于某之米柜中，谋害者名雨宫忠右卫门。捕执拘问，二人系同乡，常相往来，此日该童携三千金币，过忠右之宅，忠右知其赍大金，顿起不良，缢而杀之，夺其金，隐匿尸体于米柜中，以布裹之，意将托邻人而弃诸江云。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四亦阳刚不中，四处外卦之下，以刚居柔，非若三之重刚在上也，故“无咎”。“弗过遇之”，遇者不期而遇者也。《小过》“不宜上，宜下”，不可前往，往则有危，故曰“往厉必戒”，所以戒其妄动也。《彖》曰“过以利贞，与时行也”，时当夫动，以动为贞，时当夫上，以止为贞，贞在随时，不在固守，故曰“勿用永贞”。《象传》以“位不当”释“弗过遇之”，谓以阳居阴，刚而失位，示弗过五也。以“终不可长”释“往厉，必戒”，谓往则有危，不可长守其正也。此爻九家《易》谓，四进则遇五，不复过，于卦象最合。汉人言象，固有至当不易者。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问时运：运以当可之谓时，勿宜妄动轻进。</p><p>○　问营商：得可而止，切勿过贪。</p><p>○　问功名：不求躁进，自得巷遇之庆，若妄动希荣，恐反遭祸。</p><p>○　问战征：四刚而失位，宜勿进攻，乃可无咎。</p><p>○　问婚姻：自有良缘，得时则遇，宜勿急急媒聘。</p><p>○　问家宅：安居为宜，无用迁移。</p><p>○　问六甲：生男。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>友人某来，请占借贷钱财，筮得《小过》之《谦》。</p><p>断曰：四处《震》之始，《震》为动，动则思欲前往。自四往上，必先过五，爻曰“弗过”，当自有礼遇，礼遇即在五也。遇则反危，必当戒慎。今占借贷，得《小过》四爻，知足下为借贷而前往。四与五比，不可过也，“弗过”于五，必有相遇于五也。五爻曰“密云不雨”，则大惠必难望矣；又曰“弋取彼在穴”，则小惠当必得也。若越五而往，不特无获，且致危厉，所当自戒。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>“密云不雨”，与《小畜》《彖》辞同，言其不能济大事，即《彖》辞所云“不可大事”之义也。六五以阴居尊，阴之盛也，阴盛则有云雨之象。五互《兑》为密，故曰“密云”；《兑》又属西，故曰“西郊”；上《震》下《艮》，《震》动而《艮》止之，故曰“不雨”。盖《小过》盛阴在外，阳气伏藏，是以密云而不雨也。云之占自东而西则雨，自西而东则不雨，故曰“自我西郊”。《易》例，大事称王，小事称公，《小过》“可小事，不可大事”，故曰“公”“穴”。卦自《坎》来，《坎》为隐伏，穴之象，《坎》又为弓，为弧，弋之象。弋所以取飞鸟也，故曰“公弋取彼在穴”。“密云不雨”，是“不可大事”也；弋取在穴，是“可小事”也。“不宜上”，故云在上而不雨，宜于下，故穴在下而可弋。五为卦主，故《彖》之旨，皆于五发之。《象传》曰“已上也”，亦即以释《彖》“不宜上”之意也。</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问时运：运途平平，难成大事，只可小受。</p><p>○　问营商：小利可占。</p><p>○　问功名：伏处山林，当有弓旌下逮。</p><p>○　问战征：敌于山穴中，设有埋伏，宜先攻取之。</p><p>○　问婚姻：是钻穴隙以相从者，非正娶也。</p><p>○　问天时：大旱。</p><p>○　问失物：当就穴地中觅之。</p><p>○　问疾病：宜用针刺之法治之。</p><p>○　问六甲：生男。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>三十年，占陆军省气运，筮得《小过》之《咸》。</p><p>断曰：云行雨施者，动象也，《震》动而《艮》止之，故有云而不雨。《艮》为穴，《震》为逐，象弋取，是穴在下，而《震》取之，即《彖》“宜下”之谓也。爻象谓雨不下降，是“不可大事”；谓穴而可取，是为可以小事。今占陆军气运，得此爻辞，陆为旱地，本不取雨。西方属金，金兵象，我国居东，兵必西行，西郊正行兵之地也。穴亦陆地，可以伏兵，“公”指陆军之大臣也。弋本军政所必需，或于军隙之暇，猎彼山野，弋取飞鸟，以供军食。弋本小事，无不可也，知本年陆军，无大动作，可相安无事也。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上爻重阴不中，居全卦之极，上与初为终始，故初曰“飞鸟”，上亦曰“飞鸟”。四曰“弗过遇之”，上曰“弗遇过之”，其义大反。“弗过”者，谓弗过于五，而自得所遇，遇则无咎也；“弗遇”者，谓不过于五，而复欲遇之，遇则必凶也。位处卦外，象为鸟翼，与初并飞，初当始飞，已知其凶，上则其飞己极，故凶尤甚。罗网高张，欲脱不得，《诗》所咏“鱼网之设，鸿则离之”是也。以亢致灾，违“不宜上”之戒也，故《象传》即以“亢”释之。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：高而愈危，进而愈厉，不知退守，凶由自取也。</p><p>○　问功名：躁进取祸。</p><p>○　问营商：既不遇时，又复妄进，必致取败。</p><p>○　问战征：凡行军前进，不遇敌兵，知敌军必于暗地设伏，宜即退军，否则必陷险难。</p><p>○　问婚姻：防坠奸媒之计。</p><p>○　问六甲：生男。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>友人某来，请占其子疾病，筮得《小过》之《旅》。</p><p>断曰：卦象似飞鸟，上为鸟翼，鸿毛遇顺风，飞鸟之所顾也，乃不遇而复过之，是鸟之飞而不止者，取凶之道也。今足下占子病，得此爻辞，上处《震》之极，《震》为长子，知足下必长子患病，爻象重阴不中，知病必是过寒之症，医者不察其过寒，而复以寒凉之剂进之，是以病愈凶也。鸟离罗网，是谓活捕，尚未致死，其病犹可望生。此爻已终，下卦《既济》，《既济》者，谓得济夫险也，如此则病又可挽回矣。</p>',108)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
